function StartScreen({ numQuestions }) {
  return (
    <div className="start">
      <h3> Welcome to the React Quiz!</h3>

      <p>{numQuestions} question to test your mastery</p>

      <button> Let's start!</button>
    </div>
  );
}

export default StartScreen;
